Translate("ruRU", "city-of-dalaran-dungeon", {
	title = "Подземелье Города Даларан",
	aliases = { "неспокойные залы Даларана" },
	sections = {
		{
			title = "Обзор",
			text = [=[Под светлым лицом отстроенного {link:city-of-dalaran}Города Даларан{/link} лежит город, которым его хозяева больше не владеют вполне. Маги возвели {link:dalaran}Даларан{/link} заново за своим великим барьером, а когда барьер пал, открыли ворота, словно все было благополучно. Это не так. Местами возрожденный город выскользнул из-под власти ордена {link:kirin-tor}Кирин-Тор{/link}. Заклинания обращаются против тех, кто их творит, создания, сделанные служить, разгуливают на свободе, сырая мана обрела облик и голод, а нечто демоническое пустило корни там, где демонов быть не должно. Ордену Кирин-Тор нужна помощь, и он слишком горд, чтобы просить о ней громко.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:dalaran}Даларан{/link} уже бывал сокрушен. В {link:third-war}Третью войну{/link} {link:archimonde}Архимонд{/link} разрушил город одним заклинанием, и уцелевшие годами отстраивали его втайне. Такой труд нельзя было совершить без {link:ogres}огр{/link}омных излияний {link:arcane-magic}тайной магии{/link}, без оберегов, наложенных на обереги, и без слуг, связанных чарами. Сколько той старой силы все еще таится в камнях и сколько в них тени владыки демонов, никто за пределами ордена сказать не может. Беды внутри начались до того, как пал барьер. Стали ли они причиной его падения, пока никто не сказал.]=],
		},
		{
			title = "Наши дни",
			text = [=[Дознаватели ордена {link:kirin-tor}Кирин-Тор{/link} говорят о возмущении, которое с каждым днем становится все сильнее, и о находках с некоего пилона, которые они пока не могут объяснить. Им приказано держать город в спокойствии. Тем временем залы внизу наполнились тем, чему там быть не должно. Среди прочего там есть место, называемое Рощей Скверны, где магия Скверны просочилась в живую древесину, и блуждающие тени мертвых.]=],
		},
		{
			title = "Те, кто здесь обитает",
			text = [=[• {b}{link:arcane-anomaly}Чародейская аномалия{/link}.{/b} Магия, вырвавшаяся из своего узора.
• {b}{link:fel-ancient}Древо Скверны{/link}.{/b} Огромное существо из дерева и корней, оскверненное магией Скверны.
• {b}{link:mana-devourer}Пожиратель маны{/link}, {link:mana-elemental}Элементаль маны{/link} и {link:mana-wraith}Призрак маны{/link}.{/b} Создания сырой маны, порожденные переполняющей город силой.
• {b}{link:unstable-sentinel}Нестабильный часовой{/link}.{/b} Создание-страж, которое больше не повинуется.
• {b}{link:shade-of-the-archmage}Тень верховного мага{/link}.{/b} Призрак одного из собственных магов {link:dalaran}Даларан{/link}а.
• {b}{link:lyn-the-ignored}Лин Забытая{/link}.{/b} Некто, чью историю никто не потрудился выслушать.
• {b}{link:atrexis-the-grave-knight}Атрексис Рыцарь Могилы{/link}.{/b} Рыцарь могилы, пришедший в {link:city-of-dalaran}город магов{/link}.]=],
		},
	},
})

